int main(){try{auto graph=loadGraph("work/roundtrip-11.dmx");RetainedShotTimelineCandidate timeline(graph,2237);std::map<std::string,std::string>previous;std::set<std::string>changed;size_t events=0;std::string resourceKey;for(size_t frame=0;frame<61;++frame){int32_t tick=870833+int32_t((frame*10000+30)/60);auto step=timeline.step(tick,2,2);auto binding=readFilmSceneRenderBindingCandidate(timeline.graph(),step.shot.clip);if(binding.models.size()!=1)throw std::runtime_error("audit model count");auto overrides=readSessionMaterialOverridesCandidate(timeline.graph(),binding.models.front());auto partition=partitionSessionMaterialAlphaCandidate(overrides);auto key=sessionMaterialOverrideKeyCandidate(partition.resources);if(frame&&resourceKey!=key)throw std::runtime_error("texture resource override changed");resourceKey=key;if(partition.alpha.size()!=1||partition.alpha[0].material!="models/anno/mamagen/visor")throw std::runtime_error("dynamic alpha coverage");std::map<std::string,std::string>current;for(const auto&material:overrides)for(const auto&parameter:material.parameters){std::string identity=material.material+":"+parameter.first;auto value=sessionMaterialParameterTextCandidate(parameter.second);current.emplace(identity,value);auto old=previous.find(identity);if(frame&&old!=previous.end()&&old->second!=value){std::cout<<"frame="<<frame<<" tick="<<tick<<" material_parameter="<<identity<<" before="<<old->second<<" after="<<value<<"\n";changed.insert(identity);++events;}}if(frame&&current.size()!=previous.size())throw std::runtime_error("material schema changed");previous=std::move(current);}std::cout<<"animated material audit frames=61 changed_parameters="<<changed.size()<<" change_events="<<events<<" resource_key_stable=1 alpha_partition_checked=1 native_shader_behavior=unverified\n";return 0;}catch(const std::exception&e){std::cerr<<e.what();return 1;}}
